def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if not alive_opponents:
        if hp <= 2 or no_water >= 2:
            return float(min(budget, 63.0))
        return float(min(budget, 24.0))

    prev_bids = []
    rich_aggressive = 0
    desperate_count = 0
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        bid = prev.get('bid') if prev else None
        if bid is not None:
            prev_bids.append(float(bid))
            if bid >= 85:
                rich_aggressive += 1
        if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 2:
            desperate_count += 1

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    scarcity = (supply <= 17)
    comfortable = (hp >= 7 and no_water == 0)
    danger = (hp <= 3 or no_water >= 2)
    caution = (hp <= 5 or no_water >= 1)

    if danger:
        base_bid = 92.0 if scarcity else 78.0
    elif caution:
        base_bid = 62.0 if scarcity else 48.0
    else:
        if rich_aggressive >= 2 and not scarcity:
            base_bid = 18.0
        elif scarcity:
            base_bid = 44.0
        else:
            base_bid = 26.0

    if highest_prev > 0:
        if highest_prev >= 100:
            if comfortable and not scarcity:
                target = 16.0
            elif danger:
                target = 88.0
            else:
                target = max(base_bid, 42.0)
        elif highest_prev >= 80:
            if comfortable and not scarcity:
                target = 20.0
            else:
                target = max(base_bid, min(74.0, highest_prev * 0.78))
        else:
            target = max(base_bid, min(76.0, highest_prev + 3.0))
    else:
        target = base_bid

    if desperate_count >= 2 and scarcity:
        target = max(target, 72.0)
    elif desperate_count >= 1 and caution:
        target = max(target, 58.0)

    reserve_days = max(0, 10 - int(day))
    soft_cap = budget
    if reserve_days > 0:
        keep_reserve = reserve_days * 14.0
        soft_cap = max(0.0, budget - keep_reserve)
        if danger:
            soft_cap = budget
        elif caution:
            soft_cap = max(soft_cap, budget * 0.55)
        else:
            soft_cap = max(soft_cap, budget * 0.28)

    final_bid = min(target, soft_cap, budget)

    if final_bid < 1.0:
        if danger:
            final_bid = min(budget, max(1.0, budget))
        else:
            final_bid = min(budget, 1.0)

    return float(max(0.0, final_bid))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    alive_opponents = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opponents.append((oid, o))

    if not alive_opponents:
        return min(budget, DAILY_SALARY * 0.4)

    # Extract yesterday bids from previous_trace for immediate reaction
    prev_bids = []
    prev_max_bid = None
    prev_high_pressure_count = 0
    for oid, o in alive_opponents:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                b = float(b)
                prev_bids.append(b)
                if prev_max_bid is None or b > prev_max_bid:
                    prev_max_bid = b
                if b >= DAILY_SALARY * 0.85:
                    prev_high_pressure_count += 1
            except Exception:
                pass

    # Estimate how many water units are likely needed this day
    # If supply is low, competition likely increases; if my HP is low, I must secure water.
    # Use a conservative target: aim to win when my HP is critical or supply is near minimum.
    supply_ratio = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY) if MAX_SUPPLY > MIN_SUPPLY else 0.5
    supply_ratio = max(0.0, min(1.0, supply_ratio))

    # Base bid depends on supply scarcity
    scarcity_factor = 1.0 + (1.0 - supply_ratio) * 0.35  # up to +35% when supply is low

    # Determine urgency from HP and consecutive no-water days
    urgency = 0.0
    if hp <= 2.0:
        urgency = 1.0
    elif hp <= 4.0:
        urgency = 0.7
    elif hp <= 6.0:
        urgency = 0.4
    else:
        urgency = 0.2

    if no_water_days >= 2:
        urgency = max(urgency, 0.8)
    if no_water_days >= 3:
        urgency = 1.0

    # Use yesterday's observed high bids to set a competitive ceiling.
    # If multiple opponents pushed high (~>=77), we modestly increase to avoid being undercut.
    if prev_bids:
        target = (DAILY_SALARY * 0.55) * scarcity_factor
        if prev_high_pressure_count >= 2:
            target = max(target, (DAILY_SALARY * 0.75) * scarcity_factor)
        if prev_max_bid is not None:
            # If someone bid extremely high yesterday, we don't match fully; we slightly undercut
            # to reduce budget risk while still contesting.
            target = max(target, min(prev_max_bid * 0.92, DAILY_SALARY * 0.95) * scarcity_factor)
    else:
        target = (DAILY_SALARY * 0.55) * scarcity_factor

    # Escalate when urgency is high
    bid = target * (0.8 + 0.4 * urgency)

    # If my HP is critical, bid closer to salary cap; otherwise stay safer.
    if urgency >= 0.9:
        bid = max(bid, DAILY_SALARY * 0.85)
    elif urgency >= 0.6:
        bid = max(bid, DAILY_SALARY * 0.65)

    # Budget-aware cap: never exceed what we can pay.
    bid = min(bid, budget)

    # If budget is too low, bid all-in to prevent death if urgency is high.
    if budget <= DAILY_SALARY * 0.2:
        if urgency >= 0.7:
            return budget
        return min(budget, DAILY_SALARY * 0.1)

    # Final safety: keep within a reasonable range.
    lower_bound = 0.0
    upper_bound = min(budget, DAILY_SALARY * 1.0)
    if bid < lower_bound:
        bid = lower_bound
    if bid > upper_bound:
        bid = upper_bound

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQUIREMENT = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_active_players = len(alive_opponents) + 1

    if num_active_players == 1:
        return min(my_status['budget'], 1.0)

    current_day = day_context['day']
    current_supply = day_context['supply']

    bid = DAILY_SALARY * 0.5

    if my_status['hp'] <= 3:
        bid = DAILY_SALARY * 0.95
    elif my_status['hp'] <= 5:
        bid = DAILY_SALARY * 0.8
    elif my_status['hp'] >= 8 and my_status['budget'] > DAILY_SALARY * (EPISODE_DAYS - current_day + 1):
        bid = DAILY_SALARY * 0.45

    if current_day >= EPISODE_DAYS - 2:
        bid = max(bid, DAILY_SALARY * 0.9)
    elif current_day >= EPISODE_DAYS * 0.7:
        bid *= 1.1

    highest_prev_bid = 0.0
    eric_prev_bid = 0.0
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            highest_prev_bid = max(highest_prev_bid, prev['bid'])
            if opp['agent_id'] == 'Eric':
                eric_prev_bid = prev['bid']

    if eric_prev_bid > 0 and eric_prev_bid > DAILY_SALARY * 0.6:
        if my_status['hp'] <= 5 or current_day >= EPISODE_DAYS - 2:
            bid = max(bid, eric_prev_bid * 1.1)
        else:
            bid = max(bid, eric_prev_bid * 1.05)
    elif highest_prev_bid > 0:
        if highest_prev_bid > DAILY_SALARY * 0.4:
            bid = max(bid, highest_prev_bid + 5.0)
        else:
            bid = max(bid, highest_prev_bid + 1.0)

    if current_supply < WATER_REQUIREMENT * 2:
        if num_active_players > 1:
            bid *= 1.15
    elif current_supply < WATER_REQUIREMENT * 2.5:
        if num_active_players > 1:
            bid *= 1.05

    if my_status['no_water_days'] > 0 and my_status['hp'] <= 5:
        bid = max(bid, DAILY_SALARY * 0.95)

    final_bid = min(my_status['budget'], bid)

    if num_active_players > 1 and my_status['budget'] > 0:
        final_bid = max(final_bid, 1.0)

    if my_status['budget'] <= 0:
        final_bid = 0.0

    return final_bid
